import{_ as t,o as a,c as i,a0 as s}from"./chunks/framework.C0WKPwzJ.js";const u=JSON.parse('{"title":"Integration","description":"Add Autodevelop to a product repository, store credentials the team owns, and embed the ticket UI.","frontmatter":{"title":"Integration","description":"Add Autodevelop to a product repository, store credentials the team owns, and embed the ticket UI."},"headers":[],"relativePath":"integration.md","filePath":"integration.md","lastUpdated":1788171427000}'),o={name:"integration.md"};function n(l,e,d,r,p,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h1><p>Copyright (c) 2026 Devrecated.</p><p>How Autodevelop is wired into a product repository, how each machine signs in, and how a customer application opens the ticket UI.</p><p>Day-to-day use: <a href="./guide">Client guide</a>. Plugin install: <a href="./install">Install</a>. CLI: <a href="./cli">CLI</a>.</p><h2 id="add-autodevelop-to-a-repo" tabindex="-1">Add Autodevelop to a repo <a class="header-anchor" href="#add-autodevelop-to-a-repo" aria-label="Permalink to &quot;Add Autodevelop to a repo&quot;">​</a></h2><p>Work in the <strong>consumer</strong> product repo.</p><ol><li>Choose an instance folder slug (<code>&lt;instance&gt;</code>, kebab-case). It must not be <code>autodevelop</code> or <code>third-party</code>.</li><li>Import the plugin on one machine and reload Cursor (<a href="./install">Install</a>).</li><li>Sign in: <code>pnpm autodevelop login</code>.</li><li>An operator connects the GitHub App (<a href="./github">GitHub App</a>).</li><li>Commit only the instance trees:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.cursor/skills/&lt;instance&gt;/</span></span>
<span class="line"><span>.cursor/rules/&lt;instance&gt;/            # if you have organization-specific rules</span></span>
<span class="line"><span>.cursor/hooks/&lt;instance&gt;/            # if you have organization-specific hooks</span></span>
<span class="line"><span>.cursor/skills/&lt;instance&gt;/autodevelop/config.json</span></span>
<span class="line"><span>.cursor/skills/&lt;instance&gt;/autodevelop/people.json</span></span>
<span class="line"><span>.cursor/skills/&lt;instance&gt;/autodevelop/.policies/</span></span>
<span class="line"><span>.cursor/hooks.json                   # merge Autodevelop hooks; keep your own</span></span></code></pre></div><ol start="6"><li>Do not commit a copy of the shared plugin trees once the plugin is installed.</li><li>Fill <code>people.json</code> (<a href="./configure">Configure</a>).</li><li>Run <code>pnpm doctor</code>.</li></ol><p>Each additional developer imports the plugin, signs in, and reloads Cursor. They do not copy another organization’s instance folder.</p><h2 id="credentials-the-team-adds" tabindex="-1">Credentials the team adds <a class="header-anchor" href="#credentials-the-team-adds" aria-label="Permalink to &quot;Credentials the team adds&quot;">​</a></h2><p>Bindings are not secrets. Secrets never go in git, chat, or handbook examples.</p><table tabindex="0"><thead><tr><th>Item</th><th>Where</th><th>Secret?</th></tr></thead><tbody><tr><td>Board ids, preview project, mail allowlist</td><td>Consumer <code>config.json</code></td><td>No</td></tr><tr><td>Names, GitHub logins, emails</td><td>Consumer <code>people.json</code></td><td>PII. Do not log raw</td></tr><tr><td>GitHub CLI (operator fallback)</td><td><code>gh auth login</code> on that machine</td><td>Yes. Lives in the <code>gh</code> store</td></tr><tr><td>Staging Firebase for mail</td><td>ADC or a gitignored local staging key</td><td>Yes. Key <strong>names</strong> only in chat</td></tr><tr><td>Subscription token</td><td>Plugin <strong>Configure</strong>, <code>AUTODEVELOP_TOKEN</code>, or the CLI credentials file</td><td>Yes. Shown once. Never print it</td></tr></tbody></table><p>Do not put GitHub tokens, Firebase JSON, or the subscription token in <code>config.json</code>.</p><h2 id="embed-tickets-in-your-application" tabindex="-1">Embed tickets in your application <a class="header-anchor" href="#embed-tickets-in-your-application" aria-label="Permalink to &quot;Embed tickets in your application&quot;">​</a></h2><p>Invited members can open the same ticket UI from your product. Add a link or button and load <code>embed.js</code> from the Autodevelop ticket origin.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://tickets.example.com/?embed=1&amp;view=submit&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;autodevelop-trigger&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-autodevelop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tickets&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-autodevelop-view</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;submit&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &gt;Request a change&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://tickets.example.com/embed.js&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Replace the origin with the ticket host your operator gives you. <code>data-autodevelop-view</code> is <code>submit</code> or <code>mine</code>. Optional <code>data-autodevelop-theme</code> is a JSON object of theme tokens (<code>primary</code>, <code>background</code>, <code>foreground</code>, <code>radius</code>, <code>fontSans</code>, optional <code>logo</code>).</p><p>Sign-in stays on the Autodevelop origin. Do not put a subscription token on the customer page. Every embed surface shows Autodevelop, a Devrecated Solutions product.</p><p>Without JavaScript, the <code>href</code> opens the full ticket UI.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./configure">Configure</a></li><li><a href="./hosted">Hosted apps</a></li><li><a href="./workflows/initial-setup">Initial setup</a></li></ul>`,22)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
